shellCommands.command:
rm -rf dist && cat > src/__smoke.test.tsx <<'EOF'
import * as React from 'react';
import {renderToString} from 'react-dom/server';
import {describe, expect, it} from 'vitest';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

describe('smoke', () => {
  it('renders the table with page 1 of 42 rows and selection/sort UI', () => {
    const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
    const bodyRows = (html.match(/<tbody[\s\S]*<\/tbody>/)?.[0].match(/<tr/g) || []).length;
    const checkboxes = (html.match(/type="checkbox"/g) || []).length;
    console.log('bodyRows', bodyRows, 'checkboxes', checkboxes);
    console.log('hasSelectedCounter', html.includes('Выбрано строк: 0'));
    console.log('hasSortHeader', html.includes('Сотрудник') && html.includes('Зарплата'));
    console.log('paginationText', (html.match(/Страница[^<]*|of[^<]*|\b1\b[^<]{0,20}/g) || []).slice(0,5));
    console.log('sampleRow', html.match(/Анна Иванов[\s\S]{0,400}/)?.[0].replace(/<[^>]+>/g,' | ').slice(0,300));
    expect(bodyRows).toBe(10);
    expect(checkboxes).toBeGreaterThanOrEqual(11);
  });
});
EOF
npx vitest run src/__smoke.test.tsx 2>&1 | grep -v "npm warn" | tail -40; rm -f src/__smoke.test.tsx; echo "cleaned: $(ls src)"

cat > vitest.smoke.config.mts <<'EOF'
import {defineConfig} from 'vitest/config';
export default defineConfig({test: {server: {deps: {inline: [/@gravity-ui/]}}, css: false}});
EOF
cat > src/__smoke.test.tsx <<'EOF'
import * as React from 'react';
import {renderToString} from 'react-dom/server';
import {describe, expect, it} from 'vitest';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

describe('smoke', () => {
  it('renders the table with page 1 of 42 rows and selection/sort UI', () => {
    const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
    const tbody = html.match(/<tbody[\s\S]*?<\/tbody>/)?.[0] ?? '';
    const bodyRows = (tbody.match(/<tr/g) || []).length;
    const checkboxes = (html.match(/type="checkbox"/g) || []).length;
    console.log('RESULT bodyRows', bodyRows, 'checkboxes', checkboxes);
    console.log('RESULT counter', html.includes('Выбрано строк: 0'));
    console.log('RESULT sampleRow', tbody.replace(/<[^>]+>/g, ' | ').replace(/\s+\|/g,' |').slice(0, 300));
    console.log('RESULT pagination', (html.match(/class="g-pagination[^"]*"/g)||[]).length, html.includes('Нет данных'));
    expect(bodyRows).toBe(10);
  });
});
EOF
npx vitest run --config vitest.smoke.config.mts src/__smoke.test.tsx 2>&1 | grep -E "RESULT|PASS|FAIL|Tests|Error|expected" | head -30; rm -f src/__smoke.test.tsx vitest.smoke.config.mts; echo "cleaned: $(ls src | tr '\n' ' ') | root: $(ls | tr '\n' ' ')"
